#!/usr/bin/env node
/**
 * Packs the UI / FX art generated by tools/imagegen/jobs/ui-fx.mjs:
 *   assets/_src/maps/common/ui/{btn-*,fx-*,frame-*}.png  ->  assets/maps/common/ui/**.png  +  apps/web/public/assets/maps/common/ui/**.webp
 * Magenta chroma key -> transparent; FX sheets become horizontal strips of 256px frames.
 */
import fs from 'node:fs';
import path from 'node:path';
import sharp from 'sharp';

const ROOT = path.resolve(path.dirname(new URL(import.meta.url).pathname), '../..');
const SRC = path.join(ROOT, 'assets/_src/maps/common/ui');
const OUT = path.join(ROOT, 'assets/maps/common/ui');
const PUB = path.join(ROOT, 'apps/web/public/assets/maps/common/ui');
const log = (...a) => console.log('[pack-ui-fx]', ...a);

// ---------- raw image helpers ----------
async function loadRaw(file) {
  const { data, info } = await sharp(file).ensureAlpha().raw().toBuffer({ resolveWithObject: true });
  return { data, w: info.width, h: info.height };
}
const toSharp = (img) => sharp(img.data, { raw: { width: img.w, height: img.h, channels: 4 } });

function hsv(r, g, b) {
  const mx = Math.max(r, g, b), mn = Math.min(r, g, b), d = mx - mn;
  let h = 0;
  if (d > 0) {
    if (mx === r) h = 60 * (((g - b) / d) % 6);
    else if (mx === g) h = 60 * ((b - r) / d + 2);
    else h = 60 * ((r - g) / d + 4);
  }
  if (h < 0) h += 360;
  return [h, mx === 0 ? 0 : d / mx, mx / 255];
}
/** magenta-ness 0..1 (hue 295-340 deg, saturated) — models render "#FF00FF" anywhere from pink-magenta to violet. */
function magentaScore(r, g, b) {
  const [h, s, v] = hsv(r, g, b);
  if (h < 288 || h > 342 || v < 0.28) return 0;
  return Math.max(0, Math.min(1, (s - 0.38) / 0.22));
}
function isMagenta(r, g, b) {
  return magentaScore(r, g, b) > 0.9;
}

/** Remove background. Magenta -> global chroma key with soft edges + despill. Otherwise flood fill from borders. */
function removeBackground(img) {
  const { data, w, h } = img;
  const corners = [0, w - 1, (h - 1) * w, h * w - 1].map((i) => [data[i * 4], data[i * 4 + 1], data[i * 4 + 2]]);
  const magentaBg = corners.filter(([r, g, b]) => isMagenta(r, g, b)).length >= 2;
  if (magentaBg) {
    for (let i = 0; i < w * h; i++) {
      const r = data[i * 4], g = data[i * 4 + 1], b = data[i * 4 + 2];
      const m = magentaScore(r, g, b);
      const a = Math.round(255 * (1 - m));
      if (m > 0) {
        // despill: pull red/blue toward green
        const cap = g + 40;
        data[i * 4] = Math.min(r, cap + 30);
        data[i * 4 + 2] = Math.min(b, cap);
      }
      data[i * 4 + 3] = Math.min(data[i * 4 + 3], a);
    }
    return img;
  }
  // flood fill from borders using average corner colour
  const bg = corners.reduce((s, c) => [s[0] + c[0] / 4, s[1] + c[1] / 4, s[2] + c[2] / 4], [0, 0, 0]);
  const distOf = (i) => Math.max(Math.abs(data[i * 4] - bg[0]), Math.abs(data[i * 4 + 1] - bg[1]), Math.abs(data[i * 4 + 2] - bg[2]));
  const T = 28;
  const seen = new Uint8Array(w * h);
  const stack = [];
  for (let x = 0; x < w; x++) stack.push(x, (h - 1) * w + x);
  for (let y = 0; y < h; y++) stack.push(y * w, y * w + w - 1);
  while (stack.length) {
    const i = stack.pop();
    if (seen[i]) continue;
    seen[i] = 1;
    const d = distOf(i);
    if (d > T) continue;
    data[i * 4 + 3] = d < T * 0.6 ? 0 : Math.round(255 * ((d - T * 0.6) / (T * 0.4)));
    const x = i % w, y = (i / w) | 0;
    if (x > 0) stack.push(i - 1);
    if (x < w - 1) stack.push(i + 1);
    if (y > 0) stack.push(i - w);
    if (y < h - 1) stack.push(i + w);
  }
  return img;
}

function bboxOf(img, x0 = 0, y0 = 0, x1 = img.w, y1 = img.h, thr = 24) {
  let minX = Infinity, minY = Infinity, maxX = -1, maxY = -1;
  for (let y = y0; y < y1; y++)
    for (let x = x0; x < x1; x++)
      if (img.data[(y * img.w + x) * 4 + 3] > thr) {
        if (x < minX) minX = x;
        if (x > maxX) maxX = x;
        if (y < minY) minY = y;
        if (y > maxY) maxY = y;
      }
  if (maxX < 0) return null;
  return { x: minX, y: minY, w: maxX - minX + 1, h: maxY - minY + 1 };
}

function crop(img, b) {
  const out = Buffer.alloc(b.w * b.h * 4);
  for (let y = 0; y < b.h; y++) img.data.copy(out, y * b.w * 4, ((b.y + y) * img.w + b.x) * 4, ((b.y + y) * img.w + b.x + b.w) * 4);
  return { data: out, w: b.w, h: b.h };
}


const rect = (img, x, y, w, h) => {
  const out = Buffer.alloc(w * h * 4);
  for (let r = 0; r < h; r++) img.data.copy(out, r * w * 4, ((y + r) * img.w + x) * 4, ((y + r) * img.w + x + w) * 4);
  return { data: out, w, h };
};
async function write(rel, sharpImg) {
  const buf = await sharpImg.png().toBuffer();
  fs.mkdirSync(path.dirname(path.join(OUT, rel)), { recursive: true });
  fs.mkdirSync(path.dirname(path.join(PUB, rel)), { recursive: true });
  fs.writeFileSync(path.join(OUT, rel), buf);
  await sharp(buf).webp({ quality: 90, alphaQuality: 100 }).toFile(path.join(PUB, rel.replace(/\.png$/, '.webp')));
  log(rel);
}
const load = async (name) => {
  const f = path.join(SRC, `${name}.png`);
  if (!fs.existsSync(f)) return log('skip (missing)', name), null;
  return removeBackground(await loadRaw(f));
};

for (const name of ['btn-kill', 'btn-report']) {
  const img = await load(name);
  if (img) await write(`${name}.png`, toSharp(crop(img, bboxOf(img))).resize(192, 192, { fit: 'contain', background: { r: 0, g: 0, b: 0, alpha: 0 } }));
}

const FX = { 'fx-kill-slash': [3, 2], 'fx-report-burst': [3, 2], 'fx-witness': [3, 2] };
const FRAME = 256;
for (const [name, [cols, rows]] of Object.entries(FX)) {
  const img = await load(name);
  if (!img) continue;
  const cw = Math.floor(img.w / cols), ch = Math.floor(img.h / rows);
  const comps = [];
  for (let i = 0; i < cols * rows; i++) {
    const cell = rect(img, (i % cols) * cw, Math.floor(i / cols) * ch, cw, ch);
    const buf = await toSharp(cell).resize(FRAME, FRAME, { fit: 'contain', background: { r: 0, g: 0, b: 0, alpha: 0 } }).png().toBuffer();
    comps.push({ input: buf, left: i * FRAME, top: 0 });
  }
  await write(
    `fx/${name}.png`,
    sharp({ create: { width: FRAME * cols * rows, height: FRAME, channels: 4, background: { r: 0, g: 0, b: 0, alpha: 0 } } }).composite(comps),
  );
}

for (const name of ['frame-task-panel', 'frame-modal', 'frame-chat']) {
  const img = await load(name);
  if (img) await write(`${name}.png`, toSharp(crop(img, bboxOf(img))).resize(256, 256, { fit: 'fill' }));
}
const door = await load('frame-area-door');
if (door) {
  const c = crop(door, bboxOf(door));
  await write('frame-area-door.png', toSharp(c).resize(768, Math.round((768 * c.h) / c.w)));
}
